#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t count = 3;
    int *items = malloc(count * sizeof *items);
    if (items == NULL) {
        fputs("allocation failed\n", stderr);
        return 1;
    }

    items[0] = 14;
    items[1] = 21;
    items[2] = 28;

    size_t index = 2;
    if (index < count) {
        printf("items[%zu]=%d\n", index, items[index]);
    } else {
        fputs("index out of range\n", stderr);
    }

    free(items);
    return 0;
}

#include <stdio.h>
#include <stddef.h>

int read_item(const int *items, size_t count, size_t index, int *result) {
    if (items == NULL || result == NULL || index >= count) {
        return 0;
    }
    *result = items[index];
    return 1;
}

int main(void) {
    int values[] = { 5, 10, 15 };
    int value;

    if (read_item(values, 3, 1, &value)) {
        printf("value=%d\n", value);
    }
    if (!read_item(values, 3, 3, &value)) {
        puts("index rejected");
    }
    return 0;
}
